use super::*;
use semio_framework_value_native_owned::native_decoding::NativeDecodeRetirementRecipient;
use semio_framework_value::ErasedSnapshotRetirement;
fn observe<T>(f:impl FnOnce()->T)->(T,usize,usize){semio_framework_trace_memory_testing::observe_backing(f)}
fn receipt(owner:&mut RetainedHistoryDeflateDecode,g:RetainedCloneGrant,b:usize,r:usize)->usize{let(issued,p)=owner.take_receipt().unwrap();assert_eq!(issued,g);assert!(p.fits(g));assert_eq!((p.retained_capacity_bytes,p.released_bytes),(b,r));p.copied_bytes}
#[derive(Clone,Copy)]
struct OriginalPages<'a>{pages:&'a[&'a[u8]],page_bytes:usize,identity:OriginalWireSourceIdentity}
impl RetainedWireByteSource for OriginalPages<'_>{fn original_source_identity(&self)->OriginalWireSourceIdentity{self.identity}fn byte_at(&self,index:usize)->Option<u8>{if index>=self.identity.extent{return None}self.pages.get(index/self.page_bytes)?.get(index%self.page_bytes).copied()}}
fn hex(s:&str)->Vec<u8>{s.as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect()}
#[test]
fn original_history_deflate_receives_paid_pages_preserves_root_and_closes_original_window(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let reference:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../🔨️modules/📡️replication/📐️format/🔎️verification/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let frame=reference["compressed"].as_array().unwrap().iter().find(|frame|frame["id"]==law["fixture"]).unwrap();let mut wire=vec![0xaa];wire.extend_from_slice(&hex(frame["storedHex"].as_str().unwrap()));let end=wire.len();wire.push(0xbb);let expected=hex(frame["rawHex"].as_str().unwrap());let axes=&law["grant"];let n=|s:&str|axes[s].as_u64().unwrap()as usize;let g=RetainedCloneGrant{maximum_items:n("maximumItems"),maximum_copy_bytes:n("maximumCopyBytes"),maximum_capacity_bytes:n("maximumCapacityBytes"),maximum_release_bytes:n("maximumReleaseBytes"),maximum_depth:n("maximumDepth")};let limit=law["maximumAllocationBytes"].as_u64().unwrap()as usize;let maximum=law["maximumTurns"].as_u64().unwrap()as usize;
 for paged in[false,true]{let page_bytes=if paged{2}else{wire.len()};let pages=wire.chunks(page_bytes).collect::<Vec<_>>();let source=OriginalPages{pages:&pages,page_bytes,identity:OriginalWireSourceIdentity{range_start:0,address:wire.as_ptr()as usize,extent:wire.len(),authority:Some((43,7))}};for cut in law["cuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap()as usize;let mut callback=|_|true;let mut recipient=NativeDecodeRetirementRecipient::new();let mut control=NativeDecodeControl::new(limit,&mut callback);control.install_retirement_recipient(&mut recipient).unwrap();let (owner,b,r)=observe(||RetainedHistoryDeflateDecode::admit(&source,(1,end),expected.len(),law["maximumFrameBytes"].as_u64().unwrap()as usize,&control,g).unwrap());assert_eq!((b,r),(0,0));let mut owner=owner.unwrap();receipt(&mut owner,g,b,r);let(mut birth,mut release,mut copied)=(b,r,0);for _ in 0..maximum{if owner.produced_bytes()>=cut&&cut<expected.len()||owner.is_ready(){break}let d=owner.demands(&source,&control).unwrap();for(axis,denied)in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}].into_iter().enumerate(){if axis==2&&d.copy_bytes==0||axis==3&&d.capacity_bytes==0||axis==4&&d.release_bytes==0{continue}let(step,b,r)=observe(||owner.step(&source,&mut control,denied).unwrap());assert_eq!(step,RetainedHistoryDeflateStep::Blocked);assert_eq!((b,r),(0,0));assert!(owner.receipt().is_none())}let(step,b,r)=observe(||owner.step(&source,&mut control,g).unwrap());assert_ne!(step,RetainedHistoryDeflateStep::Blocked);copied+=receipt(&mut owner,g,b,r);birth+=b;release+=r;}
  let mut payload=None;if cut==expected.len(){assert!(owner.is_ready());assert_eq!(owner.consumed_end(),end);assert!(owner.take_ready_into(&mut payload,g).unwrap())}else{assert_eq!(owner.produced_bytes(),cut);owner.cancel();assert!(owner.take_partial_into(&mut payload,g).unwrap())}receipt(&mut owner,g,0,0);let payload=payload.as_mut().unwrap();assert_eq!(payload.compressed_source_identity(),source.original_source_identity());assert_eq!(payload.original_range(),(1,end));let identity=RetainedWireByteSource::original_source_identity(payload);assert_eq!(identity.extent,cut);assert_eq!(copied,owner.consumed_end()-1+2*cut);for index in 0..cut{assert_eq!(payload.byte_at(index),Some(expected[index]))}for _ in 0..maximum{if owner.terminal_is_empty(){break}assert_eq!(owner.demands(&source,&control).unwrap().copy_bytes,0);let(step,b,r)=observe(||owner.close_step(&source,&control,g).unwrap());assert_ne!(step,RetainedHistoryDeflateStep::Blocked);copied+=receipt(&mut owner,g,b,r);birth+=b;release+=r;}assert!(owner.terminal_is_empty());assert_eq!(RetainedWireByteSource::original_source_identity(payload),identity);for _ in 0..maximum{if payload.terminal_is_empty(){break}let(p,b,r)=observe(||payload.close_step(g).unwrap());assert!(p.fits(g));assert_eq!((p.retained_capacity_bytes,p.released_bytes),(b,r));birth+=b;release+=r;}assert!(payload.terminal_is_empty());assert_eq!(birth,release);let(_,b,r)=observe(||drop(owner));assert_eq!((b,r),(0,0));drop(control);assert!(recipient.terminal_is_empty());
 }}
}
